import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry (512x320 px → ~1.6:1 aspect)
  const planeGeometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Load the brushed metal texture
  const material = new MeshBasicNodeMaterial();
  material.colorNode = uv().xy.mul(vec3(1)).assign(texture(null));

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    material.colorNode = texture(tex);
    material.needsUpdate = true;
  });

  // Create plane mesh
  const plane = new THREE.Mesh(planeGeometry, material);
  plane.position.copy(new THREE.Vector3(3.2, -0.3, 0));
  plane.rotation.order = 'XYZ';

  // Setup cleanup
  plane.userData.cleanup = () => {
    planeGeometry.dispose();
    material.dispose();
  };

  plane.userData.handlers = {};

  return plane;
}
